// Copyright 2024 Apheleia
//
// Description:
// Apheleia Verification Library (AVL) Benchmark
//
// Implication and dependency constraints - one random field steering the legal
// values of the others, through "->" and through if / else.
//
// This file is compiled unchanged by both flavours of the benchmark. Clock and
// reset are generated by the cocotb testbench in ../cocotb/implication.py,
// which also runs the iteration loop, so the two flavours share an identical
// harness.
//
// Only the randomization itself differs, and it is the sole thing inside the
// `ifdef below.

`timescale 1ns/1ps

module implication_bench (
    input logic clk,
    input logic rst_n
);

    // Common to both flavours - lets the testbench confirm that both ran for
    // the same number of clock cycles.
    int unsigned cycles = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycles <= 0;
        end
        else begin
            cycles <= cycles + 1;
        end
    end

`ifdef BENCH_SV_RANDOMIZE
    // -----------------------------------------------------------------------
    // Randomization under test - SystemVerilog classes and constraints.
    // -----------------------------------------------------------------------

    class implication_item;

        rand bit [7:0]  mode;
        rand bit [15:0] addr;
        rand bit [7:0]  len;
        rand bit        valid;

        // The field everything else depends on.
        constraint c_mode { mode <= 8'd3; }

        // Each mode implies a different shape of transaction.
        constraint c_0 { (mode == 8'd0) -> (len == 8'd0); }
        constraint c_1 { (mode == 8'd1) -> (len <= 8'd16); }
        constraint c_2 { (mode == 8'd2) -> (addr >= 16'h1000 && addr < 16'h2000); }
        constraint c_3 { (mode == 8'd3) -> (len > 8'd200); }

        // A two sided dependency - if / else, rather than implication.
        constraint c_valid { if (len > 8'd100) valid == 1'b1;
                             else              valid == 1'b0; }

    endclass : implication_item

    implication_item item;
    bit              enable   = 1'b1;
    int unsigned     burst    = 1;
    longint unsigned checksum = 0;
    int unsigned     count    = 0;

    initial begin
        item = new();
        // Cleared for the baseline run, which measures the harness on its own.
        void'($value$plusargs("randomize=%d", enable));
        void'($value$plusargs("burst=%d", burst));
    end

    always @(posedge clk) begin
        if (rst_n && enable) begin
            repeat (burst) begin
                if (item.randomize() == 0) begin
                    $fatal(1, "randomization failed on iteration %0d", count);
                end

                if (item.mode > 8'd3) begin
                    $fatal(1, "c_mode violated : mode=%0d", item.mode);
                end
                if ((item.mode == 8'd0) && (item.len != 8'd0)) begin
                    $fatal(1, "c_0 violated : len=%0d", item.len);
                end
                if ((item.mode == 8'd1) && (item.len > 8'd16)) begin
                    $fatal(1, "c_1 violated : len=%0d", item.len);
                end
                if ((item.mode == 8'd2) &&
                    !(item.addr >= 16'h1000 && item.addr < 16'h2000)) begin
                    $fatal(1, "c_2 violated : addr=%04x", item.addr);
                end
                if ((item.mode == 8'd3) && !(item.len > 8'd200)) begin
                    $fatal(1, "c_3 violated : len=%0d", item.len);
                end
                if (item.valid != ((item.len > 8'd100) ? 1'b1 : 1'b0)) begin
                    $fatal(1, "c_valid violated : len=%0d valid=%0b", item.len, item.valid);
                end

                checksum += 64'(item.mode) + 64'(item.addr) + 64'(item.len) + 64'(item.valid);
                count    += 1;
            end
        end
    end

    final begin
        $display("BENCH_RESULT flavour=sv iterations=%0d checksum=%0d", count, checksum);
    end
`endif

endmodule : implication_bench
